async function r2Stats(bucket:Env['ATTACHMENTS']){let cursor: string|undefined,objects=0,bytes=0,rounds=0;const maxPages=10_000;do{const page=await bucket.list({cursor,limit:1000});for(const o of page.objects){objects++;bytes+=Number(o.size)||0}cursor=page.truncated?page.cursor:undefined;rounds++}while(cursor&&rounds<maxPages);return{objects,bytes,truncated:Boolean(cursor)}}
async function writeR2State(env:Env,rows:readonly (readonly [string,string])[],updatedAt:number){const statements=rows.map(([key,value])=>env.DB.prepare(`INSERT INTO admin_settings(key,value,updated_at) VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at`).bind(key,value,updatedAt));if(typeof env.DB.batch==='function'){await env.DB.batch(statements);return}await Promise.all(statements.map(statement=>statement.run()))}
async function refreshR2Stats(env:Env){const started=Date.now(),stats=await r2Stats(env.ATTACHMENTS),updatedAt=Date.now(),rows=[['r2_stats_objects',String(stats.objects)],['r2_stats_bytes',String(stats.bytes)],['r2_stats_updated_at',String(updatedAt)],['r2_stats_failed_at','0'],['r2_stats_error_code','']] as const;await writeR2State(env,rows,updatedAt);return{...stats,updatedAt,ms:Math.max(1,Date.now()-started)}}
