const inviteCode=()=>{const bytes=crypto.getRandomValues(new Uint8Array(12));let value='';for(const byte of bytes)value+=String.fromCharCode(byte);return'PV-'+btoa(value).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'')};
const inviteEncryptionKey=async(secret:string)=>crypto.subtle.importKey('raw',fromBase64url(secret),{name:'AES-GCM'},false,['encrypt','decrypt']);
const base64url=(bytes:Uint8Array)=>{let value='';for(const byte of bytes)value+=String.fromCharCode(byte);return btoa(value).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'')};
const fromBase64url=(value:string)=>Uint8Array.from(atob(value.replaceAll('-','+').replaceAll('_','/')+'='.repeat((4-value.length%4)%4)),x=>x.charCodeAt(0));
async function encryptInviteCode(code:string,secret:string){const iv=crypto.getRandomValues(new Uint8Array(12)),ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv},await inviteEncryptionKey(secret),new TextEncoder().encode(code));return{ciphertext:base64url(new Uint8Array(ciphertext)),iv:base64url(iv)}}
